import { update } from "@/api/i6000/dept";
export default {
  name: "UnitDeptAddEdit",
  props: ['fromValue', 'isShow', 'type'],
  data: function data() {
    return {
      submitParams: {},
      rules: {
        i6000DeptName: [{
          required: true,
          message: 'i6000部门名称不能为空',
          trigger: 'blur'
        }]
      },
      saveLoading: false
    };
  },
  mounted: function mounted() {
    if (this.type == 'edit') {
      this.submitParams = JSON.parse(JSON.stringify(this.fromValue));
    }
  },
  methods: {
    submit: function submit() {
      var _this = this;
      this.$refs.submitForm.validate(function (valid) {
        if (valid) {
          if (_this.type == 'add') {
            _this.saveLoading = true;
            save(_this.submitParams).then(function (res) {
              _this.saveLoading = false;
              _this.$message.success('添加成功');
              _this.$emit("close");
              _this.$emit("refreshData");
            });
          } else if (_this.type == 'edit') {
            _this.saveLoading = true;
            update(_this.submitParams).then(function (res) {
              _this.saveLoading = false;
              _this.$message.success('修改成功');
              _this.$emit("close");
              _this.$emit("refreshData");
            });
          }
        }
      });
    },
    getTitle: function getTitle(type) {
      if (type == 'add') {
        return '新 增';
      } else if (type == 'edit') {
        return '更 新';
      }
      return null;
    }
  }
};
